#[derive(Clone, Debug, PartialEq)]
pub enum Cell {
    Number(f64),
    Text(String),
    Empty,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Table {
    pub name: String,
    pub rows: Vec<Vec<Cell>>,
}

#[derive(Clone, Debug, PartialEq)]
pub struct ColumnTotal {
    pub table_name: String,
    pub present: bool,
    pub sum: f64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ColumnError {
    InvalidLabel,
    LabelOverflow,
}

fn column_index(label: &str) -> Result<usize, ColumnError> {
    if label.is_empty() || !label.bytes().all(|b| b.is_ascii_uppercase()) {
        return Err(ColumnError::InvalidLabel);
    }
    let mut value = 0usize;
    for byte in label.bytes() {
        let digit = usize::from(byte - b'A') + 1;
        value = value
            .checked_mul(26)
            .and_then(|v| v.checked_add(digit))
            .ok_or(ColumnError::LabelOverflow)?;
    }
    value.checked_sub(1).ok_or(ColumnError::LabelOverflow)
}

pub fn total_column(tables: &[Table], label: &str) -> Result<Vec<ColumnTotal>, ColumnError> {
    let index = column_index(label)?;
    Ok(tables
        .iter()
        .map(|table| {
            let mut present = false;
            let mut sum = 0.0;
            for row in &table.rows {
                if let Some(cell) = row.get(index) {
                    present = true;
                    if let Cell::Number(value) = cell {
                        sum += value;
                    }
                }
            }
            ColumnTotal {
                table_name: table.name.clone(),
                present,
                sum,
            }
        })
        .collect())
}
